from typing import Any, Literal
from fastapi import Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, ValidationError


class TableMode(BaseModel):
    model_config = ConfigDict(extra="forbid")
    mode: Literal["ai", "human"]


def register_table_mode(app: Any, runtime: Any) -> None:
    @app.post("/api/table/gm-mode")
    async def select_mode(request: Request) -> JSONResponse:
        runtime.authorize(request, "turn.submit", require_csrf=True)
        try:
            body = TableMode.model_validate(await request.json())
            # set_mode refuses active stories, fights, rolls, drafts and queued GM turns.
            runtime.gm.set_mode(body.mode)
            await runtime.gm._status_changed()
            return JSONResponse({"ok": True, "status": runtime.gm.status()})
        except (ValidationError, ValueError) as exc:
            code = "invalid_request" if isinstance(exc, ValidationError) else str(exc)
            return JSONResponse({"ok": False, "code": code}, status_code=409)
''')
